def lookup_order(order_id):
    return {"order_id": order_id, "status": "late", "refundable": True}

tools = {"lookup_order": lookup_order}
call = {"name": "lookup_order", "arguments": {"order_id": "A123"}}

def execute(call):
    if call["name"] not in tools:
        raise ValueError("unknown tool")
    if "order_id" not in call["arguments"]:
        raise ValueError("missing order_id")
    return tools[call["name"]](**call["arguments"])

result = execute(call)
print(result["status"])
print(result["refundable"])
